    38→// processes pending blocks queue on every processPendingBlocksPeriod
    39→func (s *Service) processPendingBlocksQueue() {
    40→	// Prevents multiple queue processing goroutines (invoked by RunEvery) from contending for data.
    41→	locker := new(sync.Mutex)
    42→	async.RunEvery(s.ctx, processPendingBlocksPeriod, func() {
    43→		// Don't process the pending blocks if genesis time has not been set. The chain is not ready.
    44→		if !s.chainIsStarted() {
    45→			return
    46→		}
    47→		locker.Lock()
    48→		if err := s.processPendingBlocks(s.ctx); err != nil {
    49→			log.WithError(err).Debug("Could not process pending blocks")
    50→		}
    51→		locker.Unlock()
    52→	})
    53→}
