    55→// processPendingBlocks validates, processes, and broadcasts pending blocks.
    56→func (s *Service) processPendingBlocks(ctx context.Context) error {
    57→	ctx, span := prysmTrace.StartSpan(ctx, "processPendingBlocks")
    58→	defer span.End()
    59→
    60→	// Remove old blocks from our expiration cache.
    61→	s.deleteExpiredBlocksFromCache()
    62→
    63→	// Validate pending slots before processing.
    64→	if err := s.validatePendingSlots(); err != nil {
    65→		return errors.Wrap(err, "could not validate pending slots")
    66→	}
    67→
    68→	// Sort slots for ordered processing.
    69→	sortedSlots := s.sortedPendingSlots()
    70→
    71→	span.SetAttributes(prysmTrace.Int64Attribute("numSlots", int64(len(sortedSlots))), prysmTrace.Int64Attribute("numPeers", int64(len(s.cfg.p2p.Peers().Connected()))))
    72→
    73→	randGen := rand.NewGenerator()
    74→	var parentRoots [][32]byte
    75→
    76→	// Iterate through sorted slots.
    77→	for _, slot := range sortedSlots {
    78→		// Skip processing if slot is in the future.
    79→		if slot > s.cfg.clock.CurrentSlot() {
    80→			continue
    81→		}
    82→
    83→		ctx, span := startInnerSpan(ctx, slot)
    84→
    85→		// Get blocks in the pending queue for the current slot.
    86→		blocksInCache := s.getBlocksInQueue(slot)
    87→		if len(blocksInCache) == 0 {
    88→			span.End()
    89→			continue
    90→		}
    91→
    92→		// Process each block in the queue.
    93→		for _, b := range blocksInCache {
    94→			if err := blocks.BeaconBlockIsNil(b); err != nil {
    95→				continue
    96→			}
    97→			blkRoot, err := b.Block().HashTreeRoot()
    98→			if err != nil {
    99→				return err
   100→			}
   101→
   102→			// Skip blocks that are already being processed.
   103→			if s.cfg.chain.BlockBeingSynced(blkRoot) {
   104→				log.WithField("blockRoot", fmt.Sprintf("%#x", blkRoot)).Info("Skipping pending block already being processed")
   105→				continue
   106→			}
   107→
   108→			// Remove and skip blocks already in the database.
   109→			if s.cfg.beaconDB.HasBlock(ctx, blkRoot) {
   110→				if err := s.removeBlockFromQueue(b, blkRoot); err != nil {
   111→					return err
   112→				}
   113→				continue
   114→			}
   115→
   116→			parentRoot := b.Block().ParentRoot()
   117→			inPendingQueue := s.isBlockInQueue(parentRoot)
   118→
   119→			// Check if block is bad.
   120→			keepProcessing, err := s.checkIfBlockIsBad(ctx, span, slot, b, blkRoot)
   121→			if err != nil {
   122→				return err
   123→			}
   124→			if !keepProcessing {
   125→				continue
   126→			}
   127→
   128→			// Request parent block if not in the pending queue and not in the database.
   129→			isParentBlockInDB := s.cfg.beaconDB.HasBlock(ctx, parentRoot)
   130→			if !inPendingQueue && !isParentBlockInDB && s.hasPeer() {
   131→				parentRoots = append(parentRoots, parentRoot)
   132→				continue
   133→			}
   134→			if !isParentBlockInDB {
   135→				continue
   136→			}
   137→
   138→			// Calculate the deadline time by adding three slots duration to the current time
   139→			secondsPerSlot := params.BeaconConfig().SecondsPerSlot
   140→			threeSlotDuration := 3 * time.Duration(secondsPerSlot) * time.Second
   141→			ctxWithTimeout, cancelFunction := context.WithTimeout(ctx, threeSlotDuration)
   142→			// Process and broadcast the block.
   143→			if err := s.processAndBroadcastBlock(ctxWithTimeout, b, blkRoot); err != nil {
   144→				s.handleBlockProcessingError(ctxWithTimeout, err, b, blkRoot)
   145→				cancelFunction()
   146→				continue
   147→			}
   148→			cancelFunction()
   149→
   150→			// Remove the processed block from the queue.
   151→			if err := s.removeBlockFromQueue(b, blkRoot); err != nil {
   152→				return err
   153→			}
   154→			log.WithFields(logrus.Fields{"slot": slot, "blockRoot": hex.EncodeToString(bytesutil.Trunc(blkRoot[:]))}).Debug("Processed pending block and cleared it in cache")
   155→		}
   156→		span.End()
   157→	}
   158→	return s.sendBatchRootRequest(ctx, parentRoots, randGen)
   159→}
