   202→func (s *Service) processAndBroadcastBlock(ctx context.Context, b interfaces.ReadOnlySignedBeaconBlock, blkRoot [fieldparams.RootLength]byte) error {
   203→	if err := s.processBlock(ctx, b, blkRoot); err != nil {
   204→		return errors.Wrap(err, "process block")
   205→	}
   206→
   207→	if err := s.receiveAndBroadCastBlock(ctx, b, blkRoot, b.Block().Slot()); err != nil {
