   214→func (s *Service) processBlock(ctx context.Context, b interfaces.ReadOnlySignedBeaconBlock, blkRoot [fieldparams.RootLength]byte) error {
   215→	blockSlot := b.Block().Slot()
   216→
   217→	if err := s.validateBeaconBlock(ctx, b, blkRoot); err != nil {
   218→		if !errors.Is(ErrOptimisticParent, err) {
   219→			log.WithError(err).WithField("slot", blockSlot).Debug("Could not validate block")
   220→			return err
   221→		}
   222→	}
   223→
   224→	blockEpoch, denebForkEpoch, fuluForkEpoch := slots.ToEpoch(blockSlot), params.BeaconConfig().DenebForkEpoch, params.BeaconConfig().FuluForkEpoch
   225→
   226→	roBlock, err := blocks.NewROBlockWithRoot(b, blkRoot)
   227→	if err != nil {
   228→		return errors.Wrap(err, "new ro block with root")
   229→	}
   230→
   231→	if blockEpoch >= fuluForkEpoch {
   232→		if err := s.requestAndSaveMissingDataColumnSidecars([]blocks.ROBlock{roBlock}); err != nil {
   233→			return errors.Wrap(err, "request and save missing data column sidecars")
   234→		}
   235→
   236→		return nil
   237→	}
   238→
   239→	if blockEpoch >= denebForkEpoch {
   240→		request, err := s.pendingBlobsRequestForBlock(blkRoot, b)
   241→		if err != nil {
   242→			return errors.Wrap(err, "pending blobs request for block")
   243→		}
   244→
   245→		if len(request) > 0 {
   246→			peers := s.getBestPeers()
   247→			peerCount := len(peers)
   248→
   249→			if peerCount == 0 {
   250→				return errors.Wrapf(errNoPeersForPending, "block root=%#x", blkRoot)
   251→			}
   252→
   253→			if err := s.sendAndSaveBlobSidecars(ctx, request, peers[rand.NewGenerator().Int()%peerCount], b); err != nil {
   254→				return errors.Wrap(err, "send and save blob sidecars")
   255→			}
   256→		}
   257→
   258→		return nil
   259→	}
   260→
   261→	return nil
   262→}
