   299→func (s *Service) checkIfBlockIsBad(
   300→	ctx context.Context,
   301→	span trace.Span,
   302→	slot primitives.Slot,
   303→	b interfaces.ReadOnlySignedBeaconBlock,
   304→	blkRoot [32]byte,
   305→) (keepProcessing bool, err error) {
   306→	parentIsBad := s.hasBadBlock(b.Block().ParentRoot())
   307→	blockIsBad := s.hasBadBlock(blkRoot)
   308→	// Check if parent is a bad block.
   309→	if parentIsBad || blockIsBad {
   310→		// Set block as bad if its parent block is bad too.
   311→		if parentIsBad {
   312→			s.setBadBlock(ctx, blkRoot)
   313→		}
   314→		// Remove block from queue.
   315→		s.pendingQueueLock.Lock()
   316→		if err = s.deleteBlockFromPendingQueue(slot, b, blkRoot); err != nil {
   317→			s.pendingQueueLock.Unlock()
   318→			return false, err
   319→		}
   320→		s.pendingQueueLock.Unlock()
   321→		span.End()
   322→		return false, nil
   323→	}
   324→
   325→	return true, nil
   326→}
