   328→func (s *Service) sendBatchRootRequest(ctx context.Context, roots [][32]byte, randGen *rand.Rand) error {
   329→	ctx, span := prysmTrace.StartSpan(ctx, "sendBatchRootRequest")
   330→	defer span.End()
   331→
   332→	// Exit early if there are no roots to request.
   333→	if len(roots) == 0 {
   334→		return nil
   335→	}
   336→
   337→	// Filter out roots that are already seen in pending blocks or being synced.
   338→	roots = s.filterOutPendingAndSynced(roots)
   339→
   340→	// Nothing to do, exit early.
   341→	if len(roots) == 0 {
   342→		return nil
   343→	}
   344→
   345→	// Fetch best peers to request blocks from.
   346→	bestPeers := s.getBestPeers()
   347→
   348→	// No suitable peer, exit early.
   349→	if len(bestPeers) == 0 {
   350→		log.WithField("roots", fmt.Sprintf("%#x", roots)).Debug("Send batch root request: No suitable peers")
   351→		return nil
   352→	}
   353→
   354→	// Randomly choose a peer to query from our best peers.
   355→	// If that peer cannot return all the requested blocks,
   356→	// we randomly select another peer.
   357→	randomIndex := randGen.Int() % len(bestPeers)
   358→	pid := bestPeers[randomIndex]
   359→
   360→	for range numOfTries {
   361→		req := p2ptypes.BeaconBlockByRootsReq(roots)
   362→
   363→		// Get the current epoch.
   364→		currentSlot := s.cfg.clock.CurrentSlot()
   365→		currentEpoch := slots.ToEpoch(currentSlot)
   366→
   367→		// Trim the request to the maximum number of blocks we can request if needed.
   368→		maxReqBlock := params.MaxRequestBlock(currentEpoch)
   369→		rootCount := uint64(len(roots))
   370→		if rootCount > maxReqBlock {
   371→			req = roots[:maxReqBlock]
   372→		}
   373→
   374→		// Send the request to the peer.
   375→		if err := s.sendBeaconBlocksRequest(ctx, &req, pid); err != nil {
   376→			tracing.AnnotateError(span, err)
   377→			log.WithError(err).Debug("Could not send recent block request")
   378→		}
   379→
   380→		// Filter out roots that are already seen in pending blocks.
   381→		newRoots := make([][32]byte, 0, rootCount)
   382→		func() {
   383→			s.pendingQueueLock.RLock()
   384→			defer s.pendingQueueLock.RUnlock()
   385→
   386→			for _, rt := range roots {
   387→				if !s.seenPendingBlocks[rt] {
   388→					newRoots = append(newRoots, rt)
   389→				}
   390→			}
   391→		}()
   392→
   393→		// Exit early if all roots have been seen.
   394→		// This is the happy path.
   395→		if len(newRoots) == 0 {
   396→			return nil
   397→		}
   398→
   399→		// There is still some roots that have not been seen.
   400→		// Choosing a new peer with the leftover set of oots to request.
   401→		roots = newRoots
   402→
   403→		// Choose a new peer to query.
   404→		randomIndex = randGen.Int() % len(bestPeers)
   405→		pid = bestPeers[randomIndex]
   406→	}
   407→
   408→	// Some roots are still missing after all allowed tries.
   409→	// This is the unhappy path.
   410→	log.WithFields(logrus.Fields{
   411→		"roots": fmt.Sprintf("%#x", roots),
   412→		"tries": numOfTries,
   413→	}).Debug("Send batch root request: Some roots are still missing after all allowed tries")
   414→
   415→	return nil
   416→}
