   418→// filterOutPendingAndSynced filters out roots that are already seen in pending blocks or being synced.
   419→func (s *Service) filterOutPendingAndSynced(roots [][fieldparams.RootLength]byte) [][fieldparams.RootLength]byte {
   420→	// Remove duplicates (if any) from the list of roots.
   421→	roots = dedupRoots(roots)
   422→
   423→	// Filters out in place roots that are already seen in pending blocks or being synced.
   424→	s.pendingQueueLock.RLock()
   425→	defer s.pendingQueueLock.RUnlock()
   426→
   427→	for i := len(roots) - 1; i >= 0; i-- {
   428→		r := roots[i]
   429→		if s.seenPendingBlocks[r] || s.cfg.chain.BlockBeingSynced(r) {
   430→			roots = append(roots[:i], roots[i+1:]...)
   431→			continue
   432→		}
   433→
   434→		log.WithField("blockRoot", fmt.Sprintf("%#x", r)).Debug("Requesting block by root")
   435→	}
   436→	return roots
   437→}
