   439→func (s *Service) sortedPendingSlots() []primitives.Slot {
   440→	s.pendingQueueLock.RLock()
   441→	defer s.pendingQueueLock.RUnlock()
   442→
   443→	items := s.slotToPendingBlocks.Items()
   444→
   445→	ss := make([]primitives.Slot, 0, len(items))
   446→	for k := range items {
   447→		slot := cacheKeyToSlot(k)
   448→		ss = append(ss, slot)
   449→	}
   450→	sort.Slice(ss, func(i, j int) bool {
   451→		return ss[i] < ss[j]
   452→	})
   453→	return ss
   454→}
