   456→// validatePendingSlots validates the pending blocks
   457→// by their slot. If they are before the current finalized
   458→// checkpoint, these blocks are removed from the queue.
   459→func (s *Service) validatePendingSlots() error {
   460→	s.pendingQueueLock.Lock()
   461→	defer s.pendingQueueLock.Unlock()
   462→	oldBlockRoots := make(map[[32]byte]bool)
   463→
   464→	cp := s.cfg.chain.FinalizedCheckpt()
   465→	finalizedEpoch := cp.Epoch
   466→	if s.slotToPendingBlocks == nil {
   467→		return errors.New("slotToPendingBlocks cache can't be nil")
   468→	}
   469→	items := s.slotToPendingBlocks.Items()
   470→	for k := range items {
   471→		slot := cacheKeyToSlot(k)
   472→		blks := s.pendingBlocksInCache(slot)
   473→		for _, b := range blks {
   474→			epoch := slots.ToEpoch(slot)
   475→			// remove all descendant blocks of old blocks
   476→			if oldBlockRoots[b.Block().ParentRoot()] {
   477→				root, err := b.Block().HashTreeRoot()
   478→				if err != nil {
   479→					return err
   480→				}
   481→				oldBlockRoots[root] = true
   482→				if err := s.deleteBlockFromPendingQueue(slot, b, root); err != nil {
   483→					return err
   484→				}
   485→				continue
   486→			}
   487→			// don't process old blocks
   488→			if finalizedEpoch > 0 && epoch <= finalizedEpoch {
   489→				blkRoot, err := b.Block().HashTreeRoot()
   490→				if err != nil {
   491→					return err
   492→				}
   493→				oldBlockRoots[blkRoot] = true
   494→				if err := s.deleteBlockFromPendingQueue(slot, b, blkRoot); err != nil {
   495→					return err
   496→				}
   497→			}
   498→		}
   499→	}
   500→	return nil
   501→}
