   510→// Delete block from the list from the pending queue using the slot as key.
   511→// Note: this helper is not thread safe.
   512→func (s *Service) deleteBlockFromPendingQueue(slot primitives.Slot, b interfaces.ReadOnlySignedBeaconBlock, r [32]byte) error {
   513→	mutexasserts.AssertRWMutexLocked(&s.pendingQueueLock)
   514→
   515→	blks := s.pendingBlocksInCache(slot)
   516→	if len(blks) == 0 {
   517→		return nil
   518→	}
   519→
   520→	// Defensive check to ignore nil blocks
   521→	if err := blocks.BeaconBlockIsNil(b); err != nil {
   522→		return err
   523→	}
   524→
   525→	newBlks := make([]interfaces.ReadOnlySignedBeaconBlock, 0, len(blks))
   526→	for _, blk := range blks {
   527→		blkPb, err := blk.Proto()
   528→		if err != nil {
   529→			return err
   530→		}
   531→		bPb, err := b.Proto()
   532→		if err != nil {
   533→			return err
   534→		}
   535→		if equality.DeepEqual(blkPb, bPb) {
   536→			continue
   537→		}
   538→		newBlks = append(newBlks, blk)
   539→	}
   540→	if len(newBlks) == 0 {
   541→		s.slotToPendingBlocks.Delete(slotToCacheKey(slot))
   542→		delete(s.seenPendingBlocks, r)
   543→		return nil
   544→	}
   545→
   546→	// Decrease exp time in proportion to how many blocks are still in the cache for slot key.
   547→	d := pendingBlockExpTime / time.Duration(len(newBlks))
   548→	if err := s.slotToPendingBlocks.Replace(slotToCacheKey(slot), newBlks, d); err != nil {
   549→		return err
   550→	}
   551→	delete(s.seenPendingBlocks, r)
   552→	return nil
   553→}
